select.if:
SELECT subject_id as subjectId, COUNT(*) as assignmentCount FROM assignment WHERE subject_id IN
#{id}
GROUP BY subject_id

mapper.update:
UPDATE assignment
SET status = #{status},
    is_released = #{released},
    released_at = #{releasedAt}
WHERE id = #{assignmentId}

mapper.select:
SELECT status
FROM assignment
WHERE id = #{assignmentId}

SELECT is_released
